import "server-only";
import { existsSync, readFileSync, statSync } from "node:fs";
import path from "node:path";
import type { CourseCatalog, CourseModule } from "@/lib/course/types";

/**
 * Loads the imported Titan catalog generated by `npm run content:import`.
 * The file lives in the git-ignored content-import/ folder; if it is missing
 * the app simply shows the built-in modules and placeholders.
 */
const FILE = path.join(process.cwd(), "content-import", "generated", "titan-catalog.json");
let cache: { mtime: number; data: CourseCatalog } | null = null;

export function getTitanCatalog(): CourseCatalog | null {
  // TITAN_CONTENT=off runs the app with built-in content only (used by automated tests).
  if (process.env.TITAN_CONTENT === "off" || !existsSync(FILE)) return null;
  const mtime = statSync(FILE).mtimeMs;
  if (!cache || cache.mtime !== mtime) cache = { mtime, data: JSON.parse(readFileSync(FILE, "utf8")) as CourseCatalog };
  return cache.data;
}

export function getCourseModule(key: string): CourseModule | undefined {
  return getTitanCatalog()?.modules.find((m) => m.key === key);
}
